import { QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';

function App() {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 1000 * 60 * 5,
        retry: 1
      }
    }
  });

  return (
    <QueryClientProvider client={queryClient}>
      <YourRoutes />
      {process.env.NODE_ENV === 'development' && (
        <ReactQueryDevtools initialIsOpen={false} />
      )}
    </QueryClientProvider>
  );
}

import { useQueryClient, useState } from 'react';

function DebugPanel() {
  const queryClient = useQueryClient();
  const [debugInfo, setDebugInfo] = useState<Record<string, unknown>>({});

  const inspectCache = () => {
    const queries = queryClient.getQueriesData<any>({ type: 'all' });
    const info: Record<string, unknown> = {};
    queries.forEach(([queryKey, data]) => {
      info[JSON.stringify(queryKey)] = {
        dataSize: JSON.stringify(data).length,
        state: queryClient.getQueryState(queryKey)?.status
      };
    });
    setDebugInfo(info);
  };

  return (
    <div>
      <button onClick={inspectCache}>Inspect Cache</button>
      <pre>{JSON.stringify(debugInfo, null, 2)}</pre>
    </div>
  );
}
